"""Write terraform/terraform.tfvars from credentials.env (key/secret only)."""

import shutil
from pathlib import Path

from .terraform import terraform_dir


def generate_tfvars_content(api_key: str, api_secret: str, environment_id: str = "", service_account_id: str = "") -> str:
    content = (
        "# Generated by `uv run deploy` from credentials.env — edit credentials.env, not this file.\n"
        f'confluent_cloud_api_key    = "{api_key}"\n'
        f'confluent_cloud_api_secret = "{api_secret}"\n'
    )
    if environment_id:
        content += f'environment_id             = "{environment_id}"\n'
        content += f'service_account_id         = "{service_account_id}"\n'
    return content


def write_tfvars_for_deployment(root: Path, creds: dict[str, str]) -> bool:
    """Write terraform/terraform.tfvars; False when the key/secret are missing."""
    api_key = (creds.get("TF_VAR_confluent_cloud_api_key") or "").strip()
    api_secret = (creds.get("TF_VAR_confluent_cloud_api_secret") or "").strip()
    if not (api_key and api_secret):
        return False
    env_id = (creds.get("DATAGEN_ENVIRONMENT_ID") or "").strip()
    sa_id = (creds.get("DATAGEN_SERVICE_ACCOUNT_ID") or "").strip()
    if env_id and not sa_id:
        print("Error: DATAGEN_ENVIRONMENT_ID is set but DATAGEN_SERVICE_ACCOUNT_ID is missing in credentials.env.")
        return False
    path = terraform_dir(root) / "terraform.tfvars"
    try:
        if path.exists():
            shutil.copy2(path, path.with_suffix(".tfvars.backup"))
        path.write_text(generate_tfvars_content(api_key, api_secret, env_id, sa_id))
        path.chmod(0o600)
    except OSError as e:
        print(f"Error writing {path}: {e}")
        return False
    print(f"✓ Wrote {path}")
    return True
